export const BODY: string = "\n<p>قص صورة يستغرق أقل من دقيقة عندما تعرف الخطوات: ترفع الصورة وتسحب مربعًا حول الجزء الذي تريده وتنزّل النتيجة.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية كاملة. سنرى كيف تختار نسبة وتستخدم الشبكة لتأطير أفضل وتراجع حجم الإخراج وتختار صيغة التصدير الصحيحة.</p>\n<p>في النهاية ستستطيع قص صورة ملف شخصي أو لافتة أو لقطة شاشة أو مستند دون مشاكل على أي جهاز. واحتفظ بالملف الأصلي حتى تراجع التنزيل.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: اختر الوجهة أولًا</h2>\n<p>قرر أين ستعيش الصورة المقصوصة قبل فتح الأداة: صورة ملف شخصي تحتاج مربعًا، ولافتة تحتاج مستطيلًا عريضًا، وطباعة تحتاج نسبة محددة.</p>\n<p>الوجهة تقرر النسبة، والنسبة تقرر شكل مربع التحديد: البدء بالشكل الخطأ يعني إعادة القص لاحقًا. واستخدم الصورة الأصلية، لا نسخة مضغوطة أو معدلة: القص من أفضل مصدر متاح يبقي البكسلات المحفوظة أحدة ما أمكن.</p>\n<p>افتح <a href=\"/ar/qass-as-suwar/\">أداة قاص الصور</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تقص صورة في خمس خطوات</h2>\n<p>العملية نفسها لصورة أو لقطة شاشة أو مستند ممسوح ضوئيًا: ارفع وأطّر وراجع وصدّر وتحقق من التنزيل.</p>\n<p>خذ وقتك مع خطوة التأطير: قص دقيق الآن يوفر عليك إعادة العمل عندما تبدو الصورة سيئة في وجهتها. وافتح الملف المنزّل مرة قبل استخدامه، وتأكد من أن التأطير صحيح وأن لا شيء مهم قُطع عند الحواف.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اسحب مربع التحديد فوق الجزء الذي تريد الاحتفاظ به، مستخدمًا المقابض الثمانية لتغيير حجمه من أي جانب أو زاوية.</li>\n<li>اختر إعداد نسبة مسبقًا مثل 1:1 أو 4:3 أو 16:9، أو اتركه حرًا لشكل مخصص.</li>\n<li>راجع أبعاد الإخراج بالبكسلات التي تُظهرها الأداة وتأكد من أنها كبيرة بما يكفي للوجهة.</li>\n<li>اختر صيغة التصدير والجودة، ثم انقر تنزيل لحفظ الصورة المقصوصة.</li>\n</ol>\n<h2 id=\"dragging-the-selection-box\">كيف تسحب مربع التحديد</h2>\n<p>مربع التحديد هو المستطيل الذي يحدد قصك: اسحب داخله لنقله، أو اسحب أحد المقابض الثمانية لتغيير حجمه.</p>\n<p>مقابض الزاوية تغيّر الحجم من جانبين دفعة واحدة، وهي أسرع طريقة لتأطير موضوع. ومقابض الحافة تضبط جانبًا واحدًا، ما ينفع للضبط الدقيق. وعندما تكون نسبة مسبقة نشطة، تحافظ المقابض على المربع متناسبًا: يبقى الشكل ثابتًا بينما يتغير الحجم، فيبقى المربع مربعًا.</p>\n<p>كل ما خارج المربع يُعتّم على المسرح: ذلك التعتيم يساعدك على رؤية بالضبط ما سيُحفظ وما سيُقص.</p>\n<h2 id=\"choosing-an-aspect-ratio\">كيف تختار إعداد نسبة مسبقًا</h2>\n<p>اختر 1:1 لصورة ملف شخصي مربعة أو منشور إنستغرام: يبقى المربع مربعًا تمامًا وأنت تسحبه، فيبقى التأطير متسقًا.</p>\n<p>اختر 4:3 لشكل صورة تقليدي أو قص مستند: إنه أعرض قليلًا من ارتفاعه، ما يناسب معظم الصور المطبوعة والصفحات الممسوحة ضوئيًا. واختر 16:9 للافتة عريضة أو مصغرة فيديو أو شريحة عرض: الشكل العريض يمتد عبر الشاشات دون ترك مساحة فارغة.</p>\n<p>استخدم الوضع الحر عندما لا يناسب أي إعداد مسبق: يمكنك سحب المربع إلى أي شكل، ما ينفع لقطع فقرة واحدة من صفحة أو تفصيل من صورة منتج.</p>\n<h2 id=\"using-the-grid\">كيف تستخدم شبكة قاعدة الأثلاث</h2>\n<p>تقسم الشبكة مربع التحديد إلى تسعة أجزاء متساوية: ضع الموضوع على أحد الخطوط أو عند نقطة تقاطع لتكوين أكثر طبيعية.</p>\n<p>لصورة شخصية، ضع العينين على الخط الأفقي العلوي. ولمشهد، ضع الأفق على الخط العلوي أو السفلي بدل الوسط. وتساعد الشبكة أيضًا في اكتشاف موضوع مائل: إذا جرى أفق قطريًا عبر الشبكة، فقد تحتاج الصورة إلى تقويم قبل القص أو بعده.</p>\n<p>تجاهل الشبكة عندما يعمل الموضوع أفضل في الوسط: مبنى متماثل أو شعار أو صورة شخصية أمامية غالبًا تبدو أفضل في الوسط تمامًا.</p>\n<h2 id=\"zooming-for-detail\">كيف تقرّب لتأطير دقيق</h2>\n<p>قرّب عندما يكون التفصيل الذي تريده صغيرًا: ميزة منتج أو وجه بين حشد أو سطر نص واحد يستفيد من نظرة أقرب قبل وضع التحديد.</p>\n<p>التقريب لا يغيّر جودة الإخراج: يكبّر فقط المعاينة لتستطيع وضع التحديد بدقة، ويستمر التصدير في استخدام البكسلات الأصلية. وبعد التقريب، اسحب الصورة لتمركز التفصيل ثم اضبط المربع حوله: راجع قراءة الأبعاد لتأكيد أن القص ما زال كبيرًا بما يكفي.</p>\n<p>وإذا كان القص المقرّب صغيرًا جدًا لوجهتك، وسّع المربع أو استخدم صورة مصدر أكبر: قص صغير ممدود ليناسب لافتة سيبدو ناعمًا.</p>\n<h2 id=\"checking-dimensions\">كيف تراجع أبعاد الإخراج قبل التنزيل</h2>\n<p>تُظهر الأداة أبعاد الإخراج الدقيقة بالبكسلات قبل التنزيل: هذه أهم مراجعة في العملية كلها، وتستغرق ثانيتين.</p>\n<p>قارن الرقم بما تتطلبه وجهتك: صورة ملف شخصي تحتاج بضع مئات بكسل فقط، بينما لافتة ويب قد تحتاج أكثر من ألف. وإذا كان القص صغيرًا جدًا، وسّع مربع التحديد: مربع أعرض يلتقط بكسلات أكثر، ما يمنح الوجهة المزيد للعمل به.</p>\n<p>زر تحديد الكل يعيد المربع إلى الصورة الكاملة: استخدمه عندما قصصت أكثر مما يلزم وتريد بدء التأطير مجددًا من الصفر.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير والجودة</h2>\n<p>اختر JPG للصور: يتيح منزلق الجودة موازنة حجم الملف مع التفاصيل، وضبط حول 85 إلى 90 يبقي معظم الصور بمظهر نظيف.</p>\n<p>اختر PNG للقطات الشاشة والشعارات والرسوم ذات النص: لا يفقد PNG شيئًا، فتبقى حواف الحروف حادة، ويحافظ على الشفافية عندما تحتاجها. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن منزلق الجودة يختفي لـPNG، لأن PNG ليس له ضغط فاقد للضبط. هذا طبيعي، لا خطأ في الأداة.</p>\n<h2 id=\"cropping-screenshots\">كيف تقص لقطة شاشة</h2>\n<p>الصق لقطة شاشة مباشرة بـCtrl+V لتتخطى خطوة الحفظ: تظهر الصورة في القاص فورًا، جاهزة للقص.</p>\n<p>اسحب المربع حول الجزء المهم: رسالة الخطأ أو الضبط أو الزر. واقص شريط المتصفح وشريط المهام وأي مساحة فارغة. وصدّر لقطات الشاشة كـPNG: الصيغة دون فقدان تبقي النص الصغير مقروءًا، بينما ضغط JPG يضبب حواف الحروف ويجعلها أصعب قراءة.</p>\n<p>سمِّ الملف اسمًا واضحًا، مثل message-de-error.png: اسم واضح يجعل اللقطة سهلة الإيجاد عندما ترفقها برسالة أو تقرير خطأ.</p>\n<h2 id=\"cropping-on-mobile\">كيف تقص على الهاتف أو الجهاز اللوحي</h2>\n<p>يعمل القاص بإيماءات الأصابع على شاشات اللمس: اسحب المربع بإصبع واقرص للتقريب عندما تحتاج نظرة أقرب إلى التأطير.</p>\n<p>ارفع من معرضك أو التقط صورة مباشرة: تتعامل الأداة مع الملف مثل الحاسوب تمامًا، وخيارات التصدير مطابقة. والشاشات الصغيرة تجعل التأطير الدقيق أصعب، فقرّب قبل وضع المربع: قص دقيق على الهاتف ما زال أفضل من قص متسرع على سطح المكتب.</p>\n<p>تُحفظ القصاصات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركتها إلى تطبيق محادثة أو بريد أو منشور اجتماعي دون خطوات إضافية.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة في القص</h2>\n<p>إذا لم يتغير شكل مربع التحديد، راجع إن كانت نسبة مسبقة مثبتة: بدّل إلى الوضع الحر لسحب المربع إلى أي شكل تريده.</p>\n<p>وإذا بدا القص المنزّل ضبابيًا، فالتحديد غالبًا كان صغيرًا جدًا: عُد إلى الملف الأصلي ووسّع المربع، أو ابدأ من مصدر أعلى دقة. وإذا كان للقص الشكل الخطأ لوجهتك، راجع النسبة المسبقة: قص 1:1 لن يناسب لافتة عريضة، وقص 16:9 لن يناسب مساحة ملف شخصي مربعة.</p>\n<p>وإذا بدت الصورة داكنة خارج المربع، فالمسرح هو الذي يعتم المنطقة التي ستُزال: إنه تأثير معاينة، لا تغيير في ملفك.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لقص أفضل</h2>\n<p>قص من الملف الأصلي في كل مرة: إعادة قص JPG قُص وحُفظ مسبقًا تضيف ضررًا مع كل جولة.</p>\n<p>اترك قليلًا من الهواء حول الموضوع: وجه دون مساحة فوقه يبدو ضيقًا، ومنتج يلمس الحافة يبدو كخطأ. وراجع القص بالحجم الكامل قبل التنزيل: قرّب على الوجه أو النص وتأكد من أن لا شيء مهم ناعم أو مقطوع.</p>\n<p>احفظ الملف المقصوص باسم واضح: اسم مثل banner-16x9.png ينفع بعد أشهر، بينما اسم مثل IMG_4821.png لا ينفع.</p>\n<h2 id=\"cropping-product-photos\">كيف تقص صور منتج</h2>\n<p>صور المنتج تحتاج تأطيرًا متسقًا، لأن صفحة متجر بقصاصات غير متساوية تبدو مهملة: قص كل صورة منتج بنفس النسبة لتتسق الشبكة.</p>\n<p>اترك قليلًا من المساحة حول المنتج: قص ضيق يلمس الحواف يجعل العنصر يبدو ضيقًا، بينما هامش صغير يمنحه هواءً للتنفس. واستخدم خلفية ناعمة واقص أي فوضى من الحواف: صورة منتج نظيفة بخلفية بيضاء أو فاتحة تبيع أفضل من صورة مليئة بالمشتتات.</p>\n<p>ولمتجر يعرض منتجات كثيرة، قص بنمط دفعي: نفس النسبة ونفس الهوامش ونفس الخلفية. الاتساق عبر الكتالوج كله أهم من أي قص مثالي واحد.</p>\n<h2 id=\"cropping-for-email\">كيف تقص صورًا للبريد الإلكتروني</h2>\n<p>الصور في البريد يجب أن تكون صغيرة وبالشكل الصحيح، لأن صورة كبيرة قد تدفع النص خارج الشاشة أو تجعل الرسالة تحمل ببطء.</p>\n<p>قص الصورة إلى الجزء المهم قبل إرفاقها: لقطة كاملة بتفصيل صغير لا تنفع في بريد، بينما قص ضيق للتفصيل واضح فورًا. وصدّر صور البريد كـJPG للصور وPNG للقطات الشاشة: حجم الملف الأصغر يبقي البريد خفيفًا، والصيغة الصحيحة تبقي المحتوى مقروءًا.</p>\n<p>راجع الصورة المقصوصة على هاتف قبل إرسالها: معظم البريد يُقرأ على الهاتف، وقص يبدو جيدًا على سطح المكتب قد يكون صغيرًا جدًا أو عريضًا جدًا على الهاتف.</p>\n<h2 id=\"cropping-and-accessibility\">القص وإمكانية الوصول</h2>\n<p>قص جيد يساعد الجميع، لكنه يهم أكثر لمن يرون الصور مكبرة أو بعدسات شاشة: قص ضيق للمحتوى المهم أسهل متابعة من لقطة واسعة.</p>\n<p>وعند قص مخطط أو رسم بياني، أبقِ التسميات والمفتاح داخل الإطار: رسم بياني دون تسمياته لا يعني شيئًا، مهما كان القص حادًا. وللصور التعليمية، قص خطوة واحدة في كل مرة: قص واحد واضح لكل خطوة أسهل متابعة من صورة كبيرة تُظهر العملية كلها دفعة واحدة.</p>\n<p>أضف تعليقًا قصيرًا أو نصًا بديلًا عندما تشارك صورة مقصوصة: يشرح التعليق ما يُظهره القص، ما يساعد من لا يستطيع رؤية الصورة بوضوح.</p>\n<h2 id=\"saving-crop-presets\">كيف توفر وقتًا بقصاصات قابلة للتكرار</h2>\n<p>إذا قصصت نفس النوع من الصور غالبًا، أنشئ عادة: استخدم نفس النسبة المسبقة ونفس صيغة التصدير ونفس نمط التسمية في كل مرة.</p>\n<p>روتين متسق يوفر دقائق في كل قص: تتوقف عن تقرير النسبة والصيغة من الصفر، وتبدأ في إنتاج قصاصات نظيفة دون تفكير. ودوّن النسب التي تحتاجها منصاتك: قائمة قصيرة على مكتبك، مثل ملف شخصي 1:1 ولافتة 16:9، تزيل الشك من كل جلسة قص.</p>\n<p>راجع قصاصاتك من حين لآخر: المنصات تغيّر قواعد أحجامها، ونسبة عملت العام الماضي قد لا تناسب المساحة التي تستهدفها الآن.</p>\n<p>لإرشاد حول النسب، اقرأ <a href=\"/ar/blog/nisab-qass-as-suwar-mashruha/\">نسب القص موضحة: 1:1 و4:3 و16:9 ومخصصة</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-qass-as-suwar/\">دليل قاص الصور الكامل</a>، وإذا كانت الصورة مائلة جرّب <a href=\"/ar/tadweer-wa-qalb-as-sura/\">أداة التدوير والقلب</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أقص صورة إلى مربع لإنستغرام؟","answer":"ارفع الصورة واختر النسبة المسبقة 1:1 واسحب المربع المربع فوق الجزء الذي تريده. وأبقِ الموضوع في الوسط مع قليل من الهواء، وراجع أبعاد الإخراج ثم نزّل كـJPG للصور."},{"question":"هل يمكنني قص صورة دون تثبيت أي تطبيق؟","answer":"نعم، يعمل القاص بالكامل في متصفحك على أي جهاز، دون تثبيت أو حساب. ارفع الصورة واسحب مربع التحديد واختر نسبة ونزّل النتيجة. وصورتك لا تُرفع أبدًا إلى خادم."},{"question":"ما أفضل صيغة لتنزيل لقطة شاشة مقصوصة؟","answer":"PNG، لأنه دون فقدان ويبقي النص الصغير حادًا. وضغط JPG يضبب حواف الحروف، ما يجعل اللقطات أصعب قراءة. واستخدم JPG فقط للصور المقصوصة، حيث حجم الملف الأصغر يهم أكثر."},{"question":"كيف أقص شخصًا أو شيئًا عند حافة صورة؟","answer":"اسحب مربع التحديد بحيث يبقى الشخص أو الشيء غير المرغوب خارجه ثم نزّل القص. وتُظهر المنطقة المعتمة على المسرح بالضبط ما سيُزال. وإذا كان الشيء في وسط الصورة، فالقص وحده لن يزيله."},{"question":"لماذا تبدو صورتي المقصوصة ضبابية عند رفعها؟","answer":"مربع التحديد غالبًا كان صغيرًا جدًا، فالقص له بكسلات أقل مما تحتاجه الوجهة. وعُد إلى الملف الأصلي ووسّع المربع وراجع أبعاد الإخراج قبل التنزيل."},{"question":"هل يمكنني التراجع عن قص بعد تنزيله؟","answer":"لا من الملف المنزّل، إذ يزيل القص البكسلات المقطوعة إلى الأبد. واحتفظ بالصورة الأصلية لتستطيع قصها مجددًا بشكل مختلف. وفي الأداة، استخدم زر تحديد الكل لإعادة التحديد الكامل قبل التنزيل."}];
